return ['domain'=>'publishpress-hub','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 12:25+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Sentralisadong sentro ng pamamahala para sa lahat ng PublishPress plugins - i-install, i-update, at pamahalaan ang mga lisensya mula sa isang dashboard.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Pakisuyo, maghintay habang naglo-load kami ng showcase ng mga bahagi...','AI Connections'=>'AI Connections','Please wait while we load AI connections...'=>'Pakisuyo, maghintay habang naglo-load kami ng mga AI connections...','Please wait while we load the plugins dashboard...'=>'Pakisuyo, maghintay habang naglo-load kami ng dashboard ng plugins...','Settings'=>'Mga Setting','Please wait while we load the settings page...'=>'Pakisuyo, maghintay habang naglo-load kami ng pahina ng mga setting...','You do not have sufficient permissions to access this page.'=>'Wala kang sapat na pahintulot upang ma-access ang pahinang ito.','Welcome'=>'Maligayang pagdating','Please wait while we load the welcome page...'=>'Pakisuyo, maghintay habang naglo-load kami ng pahina ng maligayang pagdating...','Language pack has not been checked yet.'=>'Ang language pack ay hindi pa nasuri.','Site locale is English. No language pack is downloaded.'=>'Ang lokal ng site ay Ingles. Walang na-download na language pack.','No language packs are registered.'=>'Walang nairehistrong mga language pack.','Language pack directory is not available.'=>'Ang direktoryo ng language pack ay hindi magagamit.','Language pack for %1$s (%2$s) matches %3$s.'=>'Ang language pack para sa %1$s (%2$s) ay tumutugma sa %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Ang language pack para sa %1$s (%2$s) ay na-install para sa %3$s.','Language pack URL was rejected.'=>'Tinanggihan ang URL ng language pack.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Nabigo ang pag-download ng language pack para sa %1$s (%2$s). Ang na-install na pack ay naiwan sa lugar.','Language pack could not be unpacked.'=>'Hindi ma-unpack ang language pack.','Language pack is missing a catalog file. The installed pack was left in place.'=>'Ang language pack ay nawawalan ng catalog file. Ang na-install na pack ay naiwan sa lugar.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'Ang JSON catalog ng language pack ay hindi wasto. Ang na-install na pack ay naiwan sa lugar.','Language pack could not be stored. The installed pack was left in place.'=>'Hindi maimbak ang language pack. Ang na-install na pack ay naiwan sa lugar.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'Hindi maitatag ang PHP catalog ng language pack. Ang na-install na pack ay naiwan sa lugar.','Warning: The license for %1$s has expired. %2$s'=>'Babala: Ang lisensya para sa %1$s ay nag-expire na. %2$s','Manage licenses'=>'Pamahalaan ang mga lisensya','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Babala: %1$d plugin(s) ay may na-expire na lisensya: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Tinanggap ng server ng lisensya ang iyong susi, ngunit hindi ma-save ng site na ito ang aktibong lisensya nito. Pakisuyo, makipag-ugnayan sa suporta at banggitin ang mensaheng ito.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'Mga aksyon ng PublishPress para sa %s. Ang mga tool na ito ay nalalapat lamang sa site na ito. Kung maraming site ang konektado at hindi malinaw ang hiniling na site, tanungin kung aling site ang gagamitin bago tumawag ng tool. Kumpirmahin ang target na site bago baguhin ang data ng site.','WordPress version'=>'Bersyon ng WordPress','MCP Adapter version'=>'Bersyon ng MCP Adapter','Not active'=>'Hindi aktibo','HTTPS'=>'HTTPS','Available'=>'Magagamit','Required'=>'Kinakailangan','Application passwords'=>'Mga application na password','Unavailable; check WordPress or security plugin settings'=>'Hindi magagamit; suriin ang mga setting ng WordPress o security plugin','Registered actions'=>'Nairehistrong mga aksyon','Selected actions exposed'=>'Napiling mga aksyon na ipapakita','Changes saved.'=>'Nailigtas ang mga pagbabago.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Nailigtas ang mga pagbabago. I-restart ang iyong AI app o i-refresh ang koneksyon nito sa PublishPress upang i-update ang mga magagamit na aksyon.','Changes saved. Connect your AI app to continue.'=>'Nailigtas ang mga pagbabago. Ikonekta ang iyong AI app upang magpatuloy.','Changes saved. Select at least one available action to continue.'=>'Nailigtas ang mga pagbabago. Pumili ng hindi bababa sa isang magagamit na aksyon upang magpatuloy.','Update WordPress to continue'=>'I-update ang WordPress upang magpatuloy','WordPress 6.9 or newer is required.'=>'Kinakailangan ang WordPress 6.9 o mas bago.','Open WordPress updates'=>'Buksan ang mga update ng WordPress','Install the MCP Adapter plugin'=>'I-install ang MCP Adapter plugin','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'I-install ang opisyal na WordPress MCP Adapter plugin upang ikonekta ang iyong AI service.','Manage plugins'=>'Pamahalaan ang mga plugin','Set up MCP Adapter'=>'I-set up ang MCP Adapter','Use HTTPS to connect your AI'=>'Gumamit ng HTTPS upang ikonekta ang iyong AI','Both WordPress and site addresses must use HTTPS.'=>'Parehong ang WordPress at ang mga address ng site ay dapat gumamit ng HTTPS.','Open site settings'=>'Buksan ang mga setting ng site','Add a PublishPress plugin with AI actions'=>'Magdagdag ng PublishPress plugin na may mga aksyon ng AI','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'Wala kang anumang na-install na PublishPress plugin na sumusuporta sa mga aksyon ng AI.','Open PublishPress plugins'=>'Buksan ang mga PublishPress plugin','Allow application passwords for your account'=>'Payagan ang mga application password para sa iyong account','Create an application password in your WordPress profile for assisted or manual setup.'=>'Lumikha ng isang application password sa iyong WordPress profile para sa pinadali o manu-manong setup.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Hindi magagamit ang mga application password para sa iyong account. Maaaring kailanganin ng atensyon ang mga setting ng HTTPS o security plugin.','Open application passwords'=>'Buksan ang mga application password','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'PASTE_YOUR_APPLICATION_PASSWORD_HERE','Ask my AI to help'=>'Hilingin sa aking AI na tumulong','Recommended. Ask your AI for a setup script to run on your computer.'=>'Inirerekomenda. Hilingin sa iyong AI para sa isang script ng setup upang patakbuhin sa iyong computer.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Ikonekta ang aking AI app sa PublishPress. Lumikha ng isang setup script at bigyan ako ng eksaktong utos sa terminal upang patakbuhin ito.

1. Hilingin sa akin na pumili ng aking AI app at OS (Windows, macOS o Linux). Gumamit ng interactive na pagpipilian kung magagamit, kung hindi, mga numeradong opsyon.
2. Lumikha ng script gamit ang iyong mga tool sa file. Hilingin ang partikular na pahintulot kung kinakailangan. Kung hindi ka makapagsulat nang lokal, idugtong ang isang downloadable script. Bumalik lamang sa code na may mga tagubilin sa pag-save kapag wala nang posible. Gumamit ng PowerShell sa Windows at isang angkop na script sa macOS o Linux. Huwag huminto sa pagpapaliwanag ng mga limitasyon sa pag-access o magbigay lamang ng JSON.
3. I-configure ang lokal na stdio server na ito:
Pangalan: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Basahin ang WP_API_PASSWORD sa pamamagitan ng isang nakatagong prompt ng terminal.
Hub write access: %5$s. Tanging mga indibidwal na napiling aksyon ang naipapakita.
4. Suriin ang Node.js at npx. Kung nawawala, i-link sa opisyal na installer at sabihin sa akin na muling buksan ang terminal. I-backup ang umiiral na mga setting. Gumamit ng JSON/TOML parser o suportadong utos ng client upang pagsamahin lamang ang server na ito, pinananatili ang iba pang mga setting at site. Huminto sa hindi wastong configuration o nakakasalungat na endpoint. Kung pinapalitan ang isang lumang PublishPress desktop extension para sa site na ito, gabayan ako na i-disable lamang ang extension na iyon upang maiwasan ang mga duplicate na koneksyon. I-quote ang mga path at halaga ng ligtas.
5. Bigyan ng maikling run, restart at approval na mga tagubilin. Suriin sa pamamagitan ng koneksyon o bigyan ako ng prompt upang subukan sa app: kumpirmahin ang URL ng site, ilista ang mga aktwal na tool at magsagawa ng read-only na lookup. Iulat kung ang mga tool sa pagsusulat ay magagamit. Kung ang mga inaasahang tool sa pagsusulat ay nawawala, hilingin sa akin na suriin ang Payagan ang mga aksyon na nagbabago ng data ng site at ang mga napiling aksyon sa Hub, pagkatapos ay i-refresh ang koneksyon. Huwag mag-claim ng tagumpay mula sa na-save na configuration lamang. Huwag subukan ang mga pagsusulat sa panahon ng setup. Linawin ang target na site kapag hindi malinaw at hilingin ang pagsusuri bago baguhin ang data ng site.</source>
<t i="30">na-enable','disabled'=>'na-disable','Set up manually'=>'I-set up nang manu-mano','Copy the configuration into your MCP client.'=>'Kopyahin ang configuration sa iyong MCP client.','Actions available through PublishPress Hub.'=>'Mga aksyon na magagamit sa pamamagitan ng PublishPress Hub.','List WordPress users'=>'Ilista ang mga gumagamit ng WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Hanapin ang mga gumagamit ayon sa pangalan o papel. Ang opsyonal na primitive capability filter ay nag-check ng epektibong access sa loob ng bawat candidate page. Bisitahin ang lahat ng total_pages kahit na ang isang filtered na pahina ay walang laman. Walang mga email address o lihim na ibinabalik.','Get WordPress user capabilities'=>'Kumuha ng mga kakayahan ng gumagamit ng WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Tukuyin ang eksaktong isang user_id o username at ibalik ang kanilang pagkakakilanlan, mga papel at epektibong primitive capabilities. Huwag kailanman hulaan ang isang user ID. Ang mga object-specific na pahintulot ay nangangailangan ng hiwalay na pagsuri para sa object na iyon.','Find WordPress content'=>'Hanapin ang nilalaman ng WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Maghanap ng mga nabasang post, pahina o isang REST-enabled na custom post type. Nagbabalik ng mga aktwal na ID, mga pamagat at permalinks. Gumamit ng post_type=page para sa mga pahina. Tukuyin ang hindi malinaw na mga pamagat bago gamitin ang isang URL. Ang default na status ay publish. Ang mga kahilingan sa pribado at draft ay nagpapatupad ng mga pahintulot ng WordPress.','List WordPress post types'=>'Ilista ang mga uri ng post ng WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Ilista ang mga nabasang REST-enabled na uri ng post at ang mga pangalan ng kakayahang ginamit para sa bawat uri. Gumamit ng mga pangalang ito para sa mga lookup ng nilalaman at mga tanong sa pahintulot.','WordPress'=>'WordPress','Create WordPress user'=>'Lumikha ng WordPress na gumagamit','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Lumikha ng bagong account ng gumagamit na may kilalang username, email at isang ma-edit na papel. Humiling ng mga nawawalang detalye. Tinatasa ng WordPress ang mga pahintulot sa pag-assign ng papel. Tinanggap ng MCP ang administrator at anumang papel na nagbibigay ng kakayahan sa antas ng administrator. Isang password ang nilikha nang pribado. Sa default, nag-eemail ang WordPress sa gumagamit ng link para sa pagsasaayos ng password. Huwag kailanman hulaan ang isang email o humiling ng password sa chat.','Create WordPress content'=>'Lumikha ng nilalaman sa WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Lumikha ng isang post, pahina o REST-enabled na custom post type. Gamitin ang post_type=page para sa mga pahina. Default ay draft. I-publish o i-schedule lamang kapag hiniling. Tinatasa ng WordPress ang mga pahintulot sa paglikha, pag-publish at pag-assign ng may-akda. Ibinabalik ang aktwal na ID at permalink.','Update WordPress content'=>'I-update ang nilalaman ng WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'I-edit ang umiiral na post, pahina o REST-enabled na custom post batay sa napatunayan na ID nito. Hanapin ang nilalaman muna kung hindi alam ang ID. Tanging mga ibinigay na field ang mababago. Tinatasa ng WordPress ang mga pahintulot sa object, pag-publish at pag-assign ng may-akda. Walang pagtanggal, arbitrary metadata o opsyon ang sinusuportahan.','Use the exact input types shown in discovery.'=>'Gamitin ang eksaktong mga uri ng input na ipinakita sa pagtuklas.','You cannot list users.'=>'Hindi mo ma-lista ang mga gumagamit.','Provide either a user ID or an exact username.'=>'Magbigay ng alinman sa isang user ID o isang eksaktong username.','No matching user belongs to this site.'=>'Walang tumutugmang gumagamit ang kabilang sa site na ito.','You cannot inspect this user.'=>'Hindi mo ma-inspect ang gumagamit na ito.','Choose a REST-enabled post type.'=>'Pumili ng REST-enabled na post type.','This post type does not support content lookup.'=>'Hindi sinusuportahan ng post type na ito ang pagtingin sa nilalaman.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'Hindi makalikha ng mga gumagamit ang mga tool ng MCP na may access sa antas ng administrator. Gamitin ang WordPress Users screen para sa pagbabagong ito.','Provide at least one content field to update.'=>'Magbigay ng hindi bababa sa isang field ng nilalaman upang i-update.','Choose an existing REST-enabled post type.'=>'Pumili ng umiiral na REST-enabled na post type.','This post type does not support content writes.'=>'Hindi sinusuportahan ng post type na ito ang pagsusulat ng nilalaman.','You cannot perform this operation.'=>'Hindi mo maaring isagawa ang operasyon na ito.','Object must be loaded before initializing.'=>'Dapat i-load ang object bago simulan.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Ang key ng lisensya na ito ay pinamamahalaan sa wp-config.php at hindi ma-edit mula sa Hub.','No license key found'=>'Walang nahanap na key ng lisensya','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Ang key ng lisensya na ito ay pinamamahalaan sa wp-config.php at hindi ma-deactivate mula sa Hub.','Invalid conflict resolution request.'=>'Hindi wastong kahilingan para sa resolusyon ng labanan.','The selected plugin is not available for activation.'=>'Ang napiling plugin ay hindi available para sa pag-activate.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Ang paglilinis ay itinigil dahil ang napiling plugin ay hindi aktibo o ang ibang bersyon ay patuloy na naka-load. Walang kopya ang nabura.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Ang napiling plugin ay aktibo, ngunit hindi maalis ang ibang bersyon. Mangyaring alisin ito mula sa Plugins screen.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Ang napiling plugin ay hindi na aktibo. Mangyaring i-reactivate ito mula sa Plugins screen.','No existing license key was found for this plugin.'=>'Walang umiiral na key ng lisensya na natagpuan para sa plugin na ito.','Database Tables'=>'Mga Talahanayan ng Database','PublishPress Plugins'=>'Mga Plugin ng PublishPress','PublishPress Hub Debug Log'=>'PublishPress Hub Debug Log','Debug Log'=>'Debug Log','The debug log is empty.'=>'Walang laman ang debug log.','Version'=>'Bersyon','Debug Mode'=>'Debug Mode','Enabled'=>'Naka-enable','Disabled'=>'Naka-disable','Generated At'=>'Nilikha Sa','Plugins'=>'Mga Plugin','No PublishPress plugins found.'=>'Walang nahanap na PublishPress plugins.','Tables'=>'Mga Talahanayan','No database table information was available.'=>'Walang magagamit na impormasyon sa database table.','Size'=>'Sukat','Engine'=>'Pang-ugnay','Rows'=>'Mga Hanay','Collation'=>'Pagsasama','Charset'=>'Charset','Total Database Size'=>'Kabuuang Laki ng Database','Not installed'=>'Hindi naka-install','Active'=>'Aktibo','Inactive'=>'Hindi aktibo','unknown'=>'hindi alam','License'=>'Lisensya','Free plugin not set for plugin family: %s'=>'Libre na plugin na hindi naitakda para sa pamilya ng plugin: %s','Pro plugin not set for plugin family: %s'=>'Pro na plugin na hindi naitakda para sa pamilya ng plugin: %s','License activation error. Please try again later or contact support for help.'=>'Error sa pag-activate ng lisensya. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','License deactivation error. Please try again later or contact support for help.'=>'Error sa pag-deactivate ng lisensya. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','This license is currently disabled. Please contact support for help.'=>'Ang lisensyang ito ay kasalukuyang hindi aktibo. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','This license has expired. Please contact support to renew it.'=>'Ang lisensyang ito ay nag-expire na. Pakisubukan makipag-ugnayan sa suporta upang i-renew ito.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Ang lisensya na ito ay hindi ma-activate. Maaaring ito ay hindi wasto, naka-block, o hindi awtorisado para sa plugin na ito. Pakisuyong suriin ang susi at makipag-ugnayan sa suporta ng PublishPress kung patuloy ang problema.','This license cannot be used for this plugin. Please contact support for help.'=>'Ang lisensyang ito ay hindi maaaring gamitin para sa plugin na ito. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Ang lisensyang ito ay hindi tumutugma sa plugin na sinusubukan mong i-activate. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','License key does not match our records. Please contact support for assistance.'=>'Ang susi ng lisensya ay hindi tumutugma sa aming mga rekord. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','No license key provided. Please enter a valid license key.'=>'Walang ibinigay na susi ng lisensya. Pakisuyong maglagay ng wastong susi ng lisensya.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'Kinakailangan ang URL ng iyong site upang i-activate ang lisensya. Pakisuyong maglagay ng wastong URL ng site upang magpatuloy.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Naabot na ang limitasyon sa pag-activate ng lisensya. Pakisubukan makipag-ugnayan sa suporta upang mag-upgrade o mag-deactivate sa ibang site.','This license cannot be activated. Please contact support for help.'=>'Ang lisensyang ito ay hindi maaaring ma-activate. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','License server error. Please try again later or contact support for help.'=>'Error sa server ng lisensya. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Ang server ng lisensya ay nagbalik ng hindi wastong tugon. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','This license is inactive for this site. Please contact support for help.'=>'Ang lisensyang ito ay hindi aktibo para sa site na ito. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','Plugin activation failed. Please try again later or contact support for help.'=>'Nabigo ang pag-activate ng plugin. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','This action is not possible because the plugin is already installed.'=>'Ang aksyong ito ay hindi posible dahil ang plugin ay naka-install na.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Nabigo ang pag-deactivate ng plugin. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','Plugin family not found. Please contact support for help.'=>'Hindi natagpuan ang pamilya ng plugin. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Ang aksyong ito ay hindi posible dahil parehong naka-install ang libre at pro na bersyon. Pakisuyong i-uninstall ang isang bersyon upang magpatuloy.','Plugin installation failed. Please contact support for help.'=>'Nabigo ang pag-install ng plugin. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Ang aksyong ito ay hindi posible dahil ang plugin ay hindi naka-activate. Pakisuyong i-activate ang plugin at subukan muli.','Plugin not found in our available plugins list. Please contact support for help.'=>'Hindi natagpuan ang plugin sa aming magagamit na listahan ng mga plugin. Pakisubukan makipag-ugnayan sa suporta para sa tulong.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Ang aksyong ito ay hindi posible dahil ang plugin ay hindi naka-install. Pakisuyong i-install ang plugin at subukan muli.','Unknown license server error. Please try again later or contact support for help.'=>'Hindi alam na error sa server ng lisensya. Pakisubukan muli mamaya o makipag-ugnayan sa suporta para sa tulong.','Sell digital products, programs, and services from your website.'=>'Magbenta ng mga digital na produkto, programa, at serbisyo mula sa iyong website.','Create and manage tags, categories, and taxonomy terms.'=>'Lumikha at pamahalaan ang mga tag, kategorya, at mga termino ng taxonomy.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Ayusin ang mga termino ng taxonomy sa mga grupo at ipakita ang mga ito sa mga ulap, tab, at listahan.','Define tasks that authors must complete before publishing.'=>'Tukuyin ang mga gawain na dapat tapusin ng mga may-akda bago mag-publish.','Control who can edit and view your content.'=>'Kontrolin kung sino ang makakapag-edit at makakakita ng iyong nilalaman.','Create, manage and display authors for your content.'=>'Lumikha, pamahalaan at ipakita ang mga may-akda para sa iyong nilalaman.','All the tools you need to improve the block editor.'=>'Lahat ng mga tool na kailangan mo upang mapabuti ang block editor.','Control your admin area and user roles.'=>'Kontrolin ang iyong admin area at mga tungkulin ng user.','Schedule changes to your posts.'=>'I-iskedyul ang mga pagbabago sa iyong mga post.','Organize, schedule, and plan your publishing.'=>'Ayusin, i-iskedyul, at planuhin ang iyong pag-publish.','Approve and schedule new versions to your published posts.'=>'Aprubahan at i-iskedyul ang mga bagong bersyon ng iyong mga na-publish na post.','Organize your posts into issues or series.'=>'Ayusin ang iyong mga post sa mga isyu o serye.','Create custom URLs for your posts and external links.'=>'Lumikha ng mga pasadyang URL para sa iyong mga post at panlabas na link.','Create custom statuses and publishing workflows.'=>'Lumikha ng mga pasadyang estado at mga daloy ng trabaho para sa pag-publish.','Dependency "%s" not found in container.'=>'Dependency "%s" ay hindi natagpuan sa container.','Error validating license: %s'=>'Error sa pag-validate ng lisensya: %s','Error getting license info: %s'=>'Error sa pagkuha ng impormasyon ng lisensya: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Tinanggihan ng lisensya ang kahilingang ito. Maaaring mangyari ito kapag ang isang license key o site ay nai-block. Mangyaring makipag-ugnayan sa PublishPress support para sa tulong.','Too many requests. Please try again later.'=>'Sobrang daming kahilingan. Mangyaring subukan muli sa ibang pagkakataon.','An error occurred while processing your request.'=>'Nagkaroon ng error habang pinoproseso ang iyong kahilingan.','Template not found: %s'=>'Template na hindi natagpuan: %s','Path cannot be empty'=>'Hindi maaaring walang laman ang landas','File extension cannot be empty'=>'Hindi maaaring walang laman ang extension ng file','Invalid file path: null byte detected'=>'Hindi wastong landas ng file: natukoy ang null byte','Invalid file path: directory traversal detected'=>'Hindi wastong landas ng file: natukoy ang directory traversal','Invalid file path: parent directory does not exist: %s'=>'Hindi wastong landas ng file: ang parent directory ay hindi umiiral: %s','Invalid file path: unable to resolve path'=>'Hindi wastong landas ng file: hindi ma-resolve ang landas','Invalid file path: operation not allowed outside permitted directories'=>'Hindi wastong landas ng file: hindi pinapayagang operasyon sa labas ng mga pinahintulutang directory','Download URL failed WordPress validation'=>'Nabigong i-validate ng WordPress ang URL ng pag-download','Downloaded plugin file does not exist'=>'Ang na-download na plugin file ay hindi umiiral','Downloaded plugin file is empty'=>'Ang na-download na plugin file ay walang laman','Cannot read downloaded plugin file'=>'Hindi mabasa ang na-download na plugin file','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'Ang na-download na file ay hindi isang wastong ZIP archive. Maaaring nagbabalik ang download URL ng isang error page.','Failed to unzip plugin file: %s'=>'Nabigong i-unzip ang plugin file: %s','Failed to unzip plugin file'=>'Nabigong i-unzip ang plugin file','Failed to activate plugin: %s'=>'Nabigong i-activate ang plugin: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'Lutasin ang mga salungatan para sa mga network-active na plugin mula sa Network Admin.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'Nabigo ang pagpapanumbalik ng activation. Ang parehong kopya ng plugin ay itinago. Mangyaring ibalik ang nakaraang bersyon mula sa Plugins screen.','The other plugin could not be deactivated.'=>'Ang ibang plugin ay hindi ma-deactivate.','The selected plugin did not remain active.'=>'Ang napiling plugin ay hindi nanatiling aktibo.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'Hindi ma-activate ang napiling plugin. Wala ring kopya ang natanggal at naibalik ang mga naunang setting ng aktibasyon.','Failed to delete plugin: %s'=>'Nabigong tanggalin ang plugin: %s','No update available for this plugin'=>'Walang update na magagamit para sa plugin na ito','Invalid update information for this plugin'=>'Hindi wastong impormasyon sa update para sa plugin na ito','Update package not available'=>'Walang magagamit na package ng update','Failed to update plugin: %s'=>'Nabigong i-update ang plugin: %s','Plugin update failed'=>'Nabigong i-update ang plugin','Invalid download URL provided'=>'Hindi wastong URL ng pag-download ang ibinigay','Download URL must use HTTP or HTTPS protocol'=>'Dapat gumamit ng HTTP o HTTPS protocol ang URL ng pag-download','Download URL is not from an allowed domain: %s'=>'Ang URL ng pag-download ay hindi mula sa pinapayagang domain: %s','Could not create a temporary package file'=>'Hindi makalikha ng pansamantalang file ng package','Failed to download plugin: %s'=>'Nabigong i-download ang plugin: %s','The plugin package download failed'=>'Nabigong i-download ang package ng plugin','Failed to get plugin information: %s'=>'Nabigong makuha ang impormasyon ng plugin: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'Hindi ma-install o ma-activate ang MCP Adapter. Gamitin ang pahina ng plugin o makipag-ugnayan sa iyong host.','MCP Adapter activated.'=>'Na-activate ang MCP Adapter.','Download prompt'=>'Download prompt','N/A'=>'N/A','Changelogs'=>'Changelogs','License key'=>'License key','Diagnostics'=>'Diagnostics','Auto-refresh'=>'Auto-refresh','ERR'=>'ERR','One-Click Installation'=>'One-Click Installation','Plugins Dashboard'=>'Plugins Dashboard','.'=>'.']];